// input-rows.js — pure helpers for the Flow-Editor Routing → Inputs list (#866).
//
// The Inputs panel is the single editor for everything that wakes an agent. A
// trigger is one of two kinds:
//   - MANUAL   — authored by a human (cron / once / http / github-event). Fully
//                editable via the reused TriggersPanel form.
//   - DERIVED  — regenerated by the reconciler from a channel[] / dataFlow port
//                (`channel: true` / `dataFlow: true`). Shown read-only; editing
//                its raw form is the §1 footgun this phase removes.
//
// These helpers are framework-free so the classification + plain-language
// wording are unit-testable without a React/DOM runtime.

import { summarizeGithubEventTrigger } from '../agent-chat/trigger-summary.js';
import { parseCronState, describeCron } from '../agent-chat/cron-format.js';

// Is this trigger reconciler-owned (derived from a channel / data-flow port)?
export function isDerivedTrigger(t) {
  return !!t && (t.channel === true || t.dataFlow === true);
}

// Split a trigger list into the human-authored (manual) and reconciler-owned
// (derived) sets, preserving order. Non-object entries are dropped.
export function partitionTriggers(triggers) {
  const manual = [];
  const derived = [];
  for (const t of Array.isArray(triggers) ? triggers : []) {
    if (!t || typeof t !== 'object') continue;
    if (isDerivedTrigger(t)) derived.push(t);
    else manual.push(t);
  }
  return { manual, derived };
}

// Find the derived listener a given channel port resolves to (#958), so the
// channel row can show the claim the BACKEND derived rather than re-deriving the
// `<wake>:wip` convention in the UI.
//
// Consolidation (#826) means the key is (artifact, label), not the channel's
// `from`: several producers over the same label share ONE listener. The artifact
// is matched through the trigger's event family, since a derived trigger carries
// no artifact field of its own.
export function derivedChannelTrigger(derived, channel) {
  if (!channel) return null;
  const label = typeof channel.label === 'string' ? channel.label.trim() : '';
  if (!label) return null; // an "opened" channel derives no label listener
  const family = channel.artifact === 'issue' ? 'issues.' : 'pull_request.';
  return (Array.isArray(derived) ? derived : []).find(t =>
    t && t.channel === true
    && (typeof t.labelFilter === 'string' ? t.labelFilter.trim() : '') === label
    && (Array.isArray(t.events) ? t.events.some(ev => typeof ev === 'string' && ev.startsWith(family)) : false),
  ) || null;
}

// A short plain-language summary of a manual trigger's firing condition, for the
// input row sentence. The github-event case defers to the shared summarizer so
// friendly event wording stays single-sourced (#778); every other type gets a
// human phrasing of its schedule / endpoint.
export function scheduleText(trigger, agentId) {
  if (!trigger || typeof trigger !== 'object') return '';
  const type = trigger.type;
  if (type === 'github-event') {
    const s = summarizeGithubEventTrigger(trigger);
    const events = s.events.length ? s.events.join(', ') : 'a repo event';
    return s.label ? `Wakes on ${events} · label “${s.label}”` : `Wakes on ${events}`;
  }
  if (type === 'cron') {
    const d = describeCron(parseCronState(trigger.cron));
    return d ? `On schedule — ${d}` : `On schedule — ${trigger.cron || '(unset)'}`;
  }
  if (type === 'once') {
    return trigger.at ? `Once at ${trigger.at}` : 'Once (time unset)';
  }
  if (type === 'http') {
    return agentId ? `Webhook — POST /hooks/${agentId}/${trigger.id}` : 'Webhook (HTTP call)';
  }
  return type || 'Trigger';
}
